        } else { // $order === 'desc'
            return $b['age'] - $a['age'];
        }
    };

    usort($set, $compareFunction);

    return $set;
}

// Example usage:
$array = [
    ['name' => 'Alice', 'address' => '123 Main St', 'age' => 25],
    ['name' => 'Bob', 'address' => '456 Elm St', 'age' => 28],
    ['name' => 'Charlie', 'address' => '789 Oak St', 'age' => 23]
];

$sortedArrayDesc = smart_sort_array($array);
print_r($sortedArrayDesc);

$sortedArrayAsc = smart_sort_array($array, 'asc');
print_r($sortedArrayAsc);
```

### Explanation:
- **$set**: This is the input array containing associative arrays where each array has keys `'name'`, `'address'`, and `'age'`.
- **$order**: A string specifying the sorting order: either 'desc' (descending) or 'asc' (ascending). By default, it's set to 'desc'.
- **usort()**: This function sorts the array using the provided compare function.
- **Compare Function** (`$compareFunction`):
  - It checks if the ages of two elements are equal; if so, it returns 0 (no change).
  - It uses the `$order` variable to determine whether to compare the age of the current element to the previous one in ascending or descending order.

